            var packages=Recognition?new[]{SpeechCatalog.Whisper,Model}:new[]{SpeechCatalog.Sherpa,Pack==null?null:Pack.Package};long size=packages.Where(p=>p!=null&&!store.Installed(p)).Sum(p=>p.Bytes);
