            install.Text=ready?"已安装":currentTask!=null&&!enqueueable?"已在后台下载":currentTask!=null?"添加到下载队列":"联网下载资源";install.Enabled=!Busy&&!ready&&enqueueable;sample.Enabled=!Busy&&ready&&!Recognition&&voice.SelectedItem!=null;
            if(!Recognition&&Pack!=null&&Pack.Package==null&&!store.VoiceReady(Pack)){resourceState.Text="导入的音色包不完整或文件已变化，请重新导入兼容ZIP包。";if(store.Installed(SpeechCatalog.Sherpa))install.Enabled=false;}
            start.Text=Busy?(actionName=="install"?"取消下载（保留进度）":"取消当前操作"):Recognition?"开始语音转文字":"生成语音";start.Enabled=Busy||ready&&(Recognition?input!=null:voice.SelectedItem!=null&&!String.IsNullOrWhiteSpace(text.Text));var result=outcomes.Get(mode);download.Visible=result!=null&&result.Files.Length>0;download.Enabled=!Busy;download.Text=outcomes.Matches(mode,Context)?"↓ 下载处理结果":"↓ 下载上次结果（输入或选项已改变）";copy.Enabled=!Busy&&transcript.TextLength>0;
