        void FillTranscript(){changing=true;var result=outcomes.Get("语音转文字");string srt=result==null?null:Path.Combine(result.Folder,"语音转文字.srt");transcript.ReadOnly=textFormat.SelectedIndex==1;transcript.Text=textFormat.SelectedIndex==0?editedText:srt!=null&&File.Exists(srt)?File.ReadAllText(srt,Encoding.UTF8):"";changing=false;}
