        void Run(string name,Func<CancellationToken,Task> task){if(Busy)return;actionName=name;operation=RunAction(task);}
        async Task RunAction(Func<CancellationToken,Task> task)
        {
            cancel=new CancellationTokenSource();StopPlayback();RefreshState();if(BusyChanged!=null)BusyChanged();progress.Indeterminate=true;
            try{await task(cancel.Token);}catch(OperationCanceledException){status.Text=actionName=="install"?"已取消下载。下载片段保留，再次点击可续传；完整资源安装前功能保持禁用。":"已取消当前操作。";}catch(Exception e){status.Text=e.Message;MessageBox.Show(this,e.Message.Length>1200?e.Message.Substring(0,1200):e.Message,"语音功能提示",MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{progress.Indeterminate=false;cancel.Dispose();cancel=null;RefreshState();if(BusyChanged!=null)BusyChanged();}
        }
