            if(!Ready)throw new IOException("请先联网下载所选引擎和模型。");var old=outcomes.Get(mode);if(old!=null&&!old.Downloaded&&old.Files.Length>0&&MessageBox.Show(this,"重新处理会清除本功能未下载结果，继续？","重新处理",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;
            string key=Context,current=mode;var result=new ResultSession();bool committed=false;bool active=true;var reporter=new Progress<Tuple<int,string>>(p=>{if(!active||IsDisposed)return;progress.Indeterminate=p.Item1<=0;progress.Value=Math.Min(99,p.Item1);status.Text=p.Item2;});
